// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testRegression_property() public {
        // Call supportsInterface with IERC1155MetadataURI interface ID
        bytes4 metadataId = type(IERC1155MetadataURI).interfaceId;
        bool result = c.supportsInterface(metadataId);
        // Reference returns true, mutant returns false
        assertTrue(result);
    }
}

interface IERC1155MetadataURI {
    function uri(uint256 id) external view returns (string memory);
}

