        address user = address(0x1);
        c.setAllowedBurningAddresses(address(this));
        c.mint(0, 5);
        // Transfer 3 of token 0 to user
        c.safeTransferFrom(address(this), user, 0, 3, "");
        c.safeTransferFrom(address(this), user, 1, 7, "");

        // Now balanceOf(user, 0) = 3, balanceOf(user, 1) = 7
        // balanceOf(this, 0) = 2, balanceOf(this, 1) = 3

        address[] memory accounts = new address[](2);
        accounts[0] = user;
        accounts[1] = address(this);
        uint256[] memory ids = new uint256[](2);
        ids[0] = 0;
        ids[1] = 1;

        uint256[] memory result = c.balanceOfBatch(accounts, ids);
        // Reference: result[0] = 3 (balanceOf(user,0)), result[1] = 3 (balanceOf(this,1))
        // Bug: result[0] = 3 (balanceOf(user,0)), result[1] = 2 (balanceOf(this,0))
        assertTrue(result[1] == 3, "Reference returns correct balance for second account and second ID");
    }
}

